-- SCR-114 advanced clearing (B-808/§26.824): partial, residual and
-- cross-currency clearing. Three normalized records linked to the
-- canonical journal — never a duplicate clearing ledger.
--
-- gl_clearing_allocation: one row per clearing line x source line,
-- carrying the amount applied. An item's remaining open balance
-- derives as its local amount minus its active allocations.
-- gl_clearing_residual: the lineage of a residual item generated by
-- a clearing — original item, residual line, reason, amount.
-- residual_reason: the tenant's residual reason master (three
-- characters at T041C parity); deactivation only, never a delete.
-- Rows are immutable history; a reset deactivates allocations rather
-- than deleting them.

create table public.residual_reason (
  client varchar(4) not null references public.client(client) on delete cascade,
  reason_code varchar(3) not null,
  description varchar(80) not null,
  is_active boolean not null default true,
  created_by varchar(60) not null default 'SYSTEM',
  created_at timestamp with time zone not null default now(),
  changed_by varchar(60),
  changed_at timestamp with time zone,
  primary key (client, reason_code)
);
--> statement-breakpoint
create table public.gl_clearing_allocation (
  client varchar(4) not null references public.client(client) on delete cascade,
  company_code varchar(10) not null,
  gl_account varchar(10) not null,
  clearing_document varchar(40) not null,
  clearing_fiscal_year integer not null,
  clearing_line_number integer not null,
  source_document varchar(40) not null,
  source_fiscal_year integer not null,
  source_line_number integer not null,
  allocated_amount numeric(23, 4) not null,
  currency char(3) not null,
  clearing_method varchar(8) not null,
  is_active boolean not null default true,
  reset_number varchar(16),
  created_by varchar(60) not null default 'SYSTEM',
  created_at timestamp with time zone not null default now(),
  changed_by varchar(60),
  changed_at timestamp with time zone,
  primary key (client, clearing_document, clearing_fiscal_year, clearing_line_number, source_document, source_fiscal_year, source_line_number),
  constraint gl_clearing_allocation_amount_positive check (allocated_amount > 0),
  constraint gl_clearing_allocation_method check (clearing_method in ('STANDARD', 'PARTIAL', 'RESIDUAL'))
);
--> statement-breakpoint
create index gl_clearing_allocation_source_idx
  on public.gl_clearing_allocation (client, company_code, gl_account, source_document, source_fiscal_year, source_line_number);
--> statement-breakpoint
create table public.gl_clearing_residual (
  client varchar(4) not null references public.client(client) on delete cascade,
  company_code varchar(10) not null,
  gl_account varchar(10) not null,
  clearing_document varchar(40) not null,
  clearing_fiscal_year integer not null,
  clearing_line_number integer not null,
  original_document varchar(40) not null,
  original_fiscal_year integer not null,
  original_line_number integer not null,
  residual_document varchar(40) not null,
  residual_fiscal_year integer not null,
  residual_line_number integer not null,
  reason_code varchar(3) not null,
  generated_amount numeric(23, 4) not null,
  currency char(3) not null,
  is_active boolean not null default true,
  reset_number varchar(16),
  created_by varchar(60) not null default 'SYSTEM',
  created_at timestamp with time zone not null default now(),
  changed_by varchar(60),
  changed_at timestamp with time zone,
  primary key (client, residual_document, residual_fiscal_year, residual_line_number),
  constraint gl_clearing_residual_amount_positive check (generated_amount > 0)
);
--> statement-breakpoint
create index gl_clearing_residual_original_idx
  on public.gl_clearing_residual (client, original_document, original_fiscal_year, original_line_number);
--> statement-breakpoint
alter table public.residual_reason enable row level security;
--> statement-breakpoint
alter table public.residual_reason force row level security;
--> statement-breakpoint
create policy tenant_isolation on public.residual_reason
  using (client = current_setting('cairn.client', true))
  with check (client = current_setting('cairn.client', true));
--> statement-breakpoint
revoke all on public.residual_reason from public;
--> statement-breakpoint
grant select, insert, update, delete on public.residual_reason to cairn_app;
